const toggle = document.querySelector('.acc__toggle');
const panel = document.querySelector('.acc__panel');

let open = false;

const render = () => {
  if (open) {
    panel.classList.add('is-open');
  } else {
    panel.classList.remove('is-open');
  }

  toggle.setAttribute('aria-expanded', String(open));

  console.log('보이는 상태:', panel.classList.contains('is-open') ? '펼침' : '접힘');
  console.log('전해지는 상태:', toggle.getAttribute('aria-expanded'));
};

toggle.addEventListener('click', () => {
  open = open ? false : true;
  render();
});

